/**
 * Pending invites for a billable role hold a seat, so the seat quota counts
 * them. A pending viewer invite is free, like the viewer it would become.
 */
export async function countPendingBillableInvitations(
  orgId: OrgId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        inArray(invitations.role, [...BILLABLE_ROLES]),
