}

/** 1 when a member in `role` occupies a seat, 0 for a free (viewer) role. */
function seatsFor(role: Role): number {
  return isBillableRole(role) ? 1 : 0;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate. Seat
 * deltas follow the recount's rule: only billable roles occupy a seat.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      const seatsUsed = seatsFor(payload.role);
      if (seatsUsed === 0) return;
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed });
    }),
    subscribe("member.role_changed", async (payload) => {
      const seatsUsed = seatsFor(payload.to) - seatsFor(payload.from);
      if (seatsUsed === 0) return;
      // A membership that is not live holds no seat, whatever its role.
      const member = await memberRepo.findMemberById(payload.orgId, payload.memberId);
      if (!member || member.status !== "active" || member.archivedAt !== null) {
        return;
      }
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed });
    }),
    subscribe("member.removed", async (payload) => {
      // The archived row keeps its role, which says whether a seat is freed.
      const member = await memberRepo.findMemberById(payload.orgId, payload.memberId);
      if (!member || !isBillableRole(member.role)) return;
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}

