/**
 * Viewers are free seats: only `owner`, `admin` and `member` count against the
 * plan's `seats` quota — on invite, on role change and in the usage counter.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { hashToken } from "@/lib/hash";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { isBillableRole } from "@/types/member";
import { rateLimitState } from "../server/_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Member, Role } from "@/types/member";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  rateLimitState.allowed = true;
  rateLimitState.remaining = 100;
});

async function memberFor(tenant: Tenant, role: Role): Promise<Member> {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`fixture ${role} missing`);
  return member;
}

async function addMember(tenant: Tenant, email: string, role: Role): Promise<Member> {
  const user = await userRepo.insertUser({ email, name: email, passwordHash: "seed" });
  return memberRepo.insertMember(tenant.org.id, user.id, role, null);
}

describe("isBillableRole", () => {
  it("bills owners, admins and members but not viewers", () => {
    expect(isBillableRole("owner")).toBe(true);
    expect(isBillableRole("admin")).toBe(true);
    expect(isBillableRole("member")).toBe(true);
    expect(isBillableRole("viewer")).toBe(false);
  });
});

describe("seat quota on invite", () => {
  // Free plan: 3 seats, filled exactly by the fixture's billable members.
  it("accepts a viewer-only batch on a full plan", async () => {
    const tenant = await createTenant("seats-viewer-batch", "free");

    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "v1@seats-viewer-batch.test", role: "viewer" },
          { email: "v2@seats-viewer-batch.test", role: "viewer" },
        ],
      }),
    ).resolves.toHaveLength(2);
  });

  it("accepts a viewer-only batch even when the plan is over quota", async () => {
    const tenant = await createTenant("seats-viewer-over", "free");
    await addMember(tenant, "extra@seats-viewer-over.test", "member");

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "v@seats-viewer-over.test",
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  it("refuses a mixed batch as a whole when its billable invites do not fit", async () => {
    const tenant = await createTenant("seats-mixed-batch", "free");

    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "v@seats-mixed-batch.test", role: "viewer" },
          { email: "m@seats-mixed-batch.test", role: "member" },
        ],
      }),
    ).rejects.toThrow(/seats/);

    await expect(invitationRepo.countPendingInvitations(tenant.org.id)).resolves.toBe(0);
  });

  it("asks for one seat per billable invite and none per viewer invite", async () => {
    // Starter: 10 seats. 3 billable from the fixture + 5 more leaves 2.
    const tenant = await createTenant("seats-batch-size", "starter");
    for (let i = 0; i < 5; i += 1) {
      await addMember(tenant, `f${i}@seats-batch-size.test`, "member");
    }

    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "a@seats-batch-size.test", role: "member" },
          { email: "b@seats-batch-size.test", role: "admin" },
          { email: "c@seats-batch-size.test", role: "viewer" },
          { email: "d@seats-batch-size.test", role: "viewer" },
        ],
      }),
    ).resolves.toHaveLength(4);

    // Now full: the pending billable invites hold the last two seats.
    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "e@seats-batch-size.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
  });

  it("does not count pending viewer invites against the quota", async () => {
    // Free: remove the member to free one seat, then queue viewer invites.
    const tenant = await createTenant("seats-pending-viewer", "free");
    const member = await memberFor(tenant, "member");
