      memberId: member.id,
      role: "viewer",
    });
    await invitationService.inviteMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      email: "m@seats-promote-pending.test",
      role: "member",
    });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "admin",
      }),
    ).rejects.toThrow(/seats/);
  });

  it("promotes a viewer when a seat is free", async () => {
    const tenant = await createTenant("seats-promote-room", "starter");
    const viewer = await memberFor(tenant, "viewer");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).resolves.toMatchObject({ role: "member" });
  });

  it("never refuses changes between billable roles or to viewer", async () => {
    const tenant = await createTenant("seats-lateral", "free");
    await addMember(tenant, "extra@seats-lateral.test", "member");
    const member = await memberFor(tenant, "member");
    const admin = await memberFor(tenant, "admin");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "admin",
      }),
    ).resolves.toMatchObject({ role: "admin" });

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: admin.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });
});

describe("seat usage counter", () => {
  it("counts billable active members only on a full recount", async () => {
    const tenant = await createTenant("seats-recount", "growth");
    await addMember(tenant, "v@seats-recount.test", "viewer");

    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.seatsUsed).toBe(3);
  });

  it("keeps the incremental adjustments in step with a full recount", async () => {
    const tenant = await createTenant("seats-deltas", "growth");
    await usageRepo.recomputeUsage(tenant.org.id);
    const off = registerUsageListeners();

    try {
      const expectInStep = async (seats: number) => {
        const cached = await usageRepo.getUsage(tenant.org.id);
        expect(cached.seatsUsed).toBe(seats);
        const recounted = await usageRepo.recomputeUsage(tenant.org.id);
        expect(recounted.seatsUsed).toBe(seats);
      };

      await expectInStep(3);

      // A viewer and a member join through invitations.
      for (const [role, token] of [
        ["viewer", "d".repeat(32)],
        ["member", "e".repeat(32)],
      ] as const) {
        const email = `${role}-joiner@seats-deltas.test`;
        await invitationRepo.insertInvitation(
          tenant.org.id,
          { orgId: tenant.org.id, email, role, expiresInDays: 14 },
          tenant.userIds.admin,
          hashToken(token),
        );
        const user = await userRepo.insertUser({ email, name: email, passwordHash: "seed" });
        await invitationService.acceptInvitation(user.id, { token });
      }
      await expectInStep(4);

      const viewer = await memberFor(tenant, "viewer");
      const member = await memberFor(tenant, "member");

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
        role: "member",
      });
      await expectInStep(5);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "admin",
      });
      await expectInStep(5);

      await memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
        role: "viewer",
      });
      await expectInStep(4);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: member.id,
      });
      await expectInStep(4);

      await memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: viewer.id,
      });
      await expectInStep(3);
    } finally {
      off();
    }
  });
});

